(function () {
    var root = document.documentElement;

    var theme;
    try { theme = localStorage.getItem("theme"); } catch (e) {}
    if (theme !== "dark" && theme !== "light") {
        theme = window.matchMedia && matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
    }
    root.style.background = theme === "dark" ? "#0b0f15" : "#dfe2e6";
    root.style.visibility = "hidden";
    root.classList.add("is-loading");
    var revealTimer = setTimeout(reveal, 3000);

    function reveal() {
        clearTimeout(revealTimer);
        root.style.visibility = "";
        root.style.background = "";
        if (document.body) void getComputedStyle(document.body).color;
        setTimeout(function () { root.classList.remove("is-loading"); }, 100);
    }

    function fetchText(url) {
        return fetch(url).then(function (res) {
            if (!res.ok) throw new Error(res.status + " " + res.statusText);
            return res.text();
        });
    }

    function insert(el, html) {
        var tpl = document.createElement("template");
        tpl.innerHTML = html;
        var waits = [];
        Array.prototype.forEach.call(tpl.content.querySelectorAll('script, link[rel="stylesheet"]'), function (node) {
            var target = node;
            if (node.tagName === "SCRIPT") {
                target = document.createElement("script");
                target.src = node.src;
                target.async = false;
                node.parentNode.replaceChild(target, node);
            }
            waits.push(new Promise(function (done) {
                target.addEventListener("load", done);
                target.addEventListener("error", done);
            }));
        });
        el.appendChild(tpl.content);
        return Promise.all(waits);
    }

    function include(el) {
        var url = el.getAttribute("include-html");
        el.removeAttribute("include-html");
        return fetchText(url)
            .then(function (html) { return insert(el, html); })
            .catch(function (err) { console.error("Could not load " + url + ": " + err.message); });
    }

    var headDone = document.head.hasAttribute("include-html") ? include(document.head) : Promise.resolve();
    headDone.then(reveal);

    var bodyDone = new Promise(function (resolve) {
        function load() {
            var elements = Array.prototype.slice.call(document.body.querySelectorAll("[include-html]"));
            Promise.all(elements.map(include)).then(resolve);
        }
        if (document.readyState === "loading") {
            document.addEventListener("DOMContentLoaded", load);
        } else {
            load();
        }
    });

    window.htmlIncludes = Promise.all([headDone, bodyDone]);
})();
